sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float wavelength;
uniform float speed;
uniform float centerX;
uniform float centerY;
half4 main(float2 coord){float2 c=float2(centerX,centerY)*size;float2 v=coord-c;float r=length(v);float wave=sin(r/wavelength*6.2831853-time*speed*6.2831853);float2 d=normalize(v+float2(0.001))*wave*amount;return image.eval(coord-d);}
